from pathlib import Path
html='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="styles.css"><title>Proyecto final</title></head><body><nav>AI Career</nav><main><h1>Gestor de solicitudes</h1><form id="form"><label>Nombre<input id="nombre" required></label><label>Correo<input id="correo" type="email" required></label><label>Mensaje<textarea id="mensaje" required></textarea></label><button>Registrar</button></form><section id="resultado"></section></main><script src="app.js"></script></body></html>'''
css='''body{font-family:Arial;margin:0;background:#eef1f5;color:#17202a}nav{padding:16px;background:#17202a;color:white}main{max-width:760px;margin:32px auto;background:white;padding:28px;border-radius:12px}label{display:block;margin:14px 0}input,textarea,button{width:100%;box-sizing:border-box;padding:12px;margin-top:6px}button{cursor:pointer}'''
js='''document.querySelector("#form").addEventListener("submit",e=>{e.preventDefault();document.querySelector("#resultado").textContent="Solicitud lista para enviar"})'''
Path("index.html").write_text(html,encoding="utf-8");Path("styles.css").write_text(css,encoding="utf-8");Path("app.js").write_text(js,encoding="utf-8");print("Frontend P2 creado")
